xml.Script:
        Colors[0] := 'EE0000'; // Red
        Colors[1] := 'FF6600'; // Orange
        Colors[2] := '0055EE'; // Blue
        Colors[3] := '00BB00'; // Green
        Colors[4] := 'FFEE00'; // Yellow
        Colors[5] := 'CCCCCC'; // LightGray

        K := 0.6;
        f := 1/sqrt(3);

        // Rotate p around normalized v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
            ca := Cos(Angle);
            sa := Sin(Angle);
            c2 := 1 - ca;

            px[i] := Xp * (Xv * c2 * Xv + ca) +
                     Yp * (Yv * c2 * Xv - sa * Zv) +
                     Zp * (Zv * c2 * Xv + sa * Yv);

            py[i] := Xp * (Xv * c2 * Yv + sa * Zv) +
                     Yp * (Yv * c2 * Yv + ca) +
                     Zp * (Zv * c2 * Yv - sa * Xv);

            pz[i] := Xp * (Xv * c2 * Zv - sa * Yv) +
                     Yp * (Yv * c2 * Zv + sa * Xv) +
                     Zp * (Zv * c2 * Zv + ca);
            Inc(i);
        end;

        i := 0;
        RotatePoint ( 1, 1, 0, -f, f,-f, -1*pi/6);
        RotatePoint ( 1, 1, 0, -f, f,-f, -3*pi/6);
        RotatePoint ( 1, 1, 0, -f, f,-f, -5*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -1*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -3*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -5*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -1*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -3*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -5*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -1*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -3*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -5*pi/6);

        // contants from Sphere macro
        C7  := K * 0.37456628469515;
        C11 := K * 0.50501585343062;
        C19 := K * 0.70388817049888;
        C24 := K * 0.85312994431035;

        // find planes' intersection point: find point on line (c7;-c7;c24)-(c11;-c11;c24) that have zero projection on axis=3 (1;-1;-1)
        x := (2 * C7 - C24) / (2 * (C7 - C11) +  (C19 - C24));
        Tx :=  C7 + (C11 - C7) * x;
        Ty := -C7 - (C11 - C7) * x;
        Tz := C24 + (C19 - C24) * x;
        // calc projection on axis=13
        D := (px[9] * Tx + py[9] * Ty + pz[9] * Tz) / sqrt(2); // D := K * 0.665679420169847;
